"""
notifier.py - HTTP notification delivery with retry and backoff

ARCHITECTURE ROLE:
    Loads delivery settings from a JSON config file and sends payloads to a
    notification endpoint. Does not own payload construction; callers pass bytes.

DESIGN CONSTRAINTS:
    - Missing or invalid config values fall back to defaults with a WARN.
      Config problems never abort delivery.
    - snd() returns None after all attempts fail rather than raising.
      Callers must check the result.
    - Backoff sleeps only between attempts, never after the final one.
"""
import http.client
import json
import logging
import math
import time
import urllib.request

logger = logging.getLogger(__name__)

DEFAULT_RETRIES = 5
DEFAULT_TIMEOUT_SECONDS = 30
DEFAULT_BACKOFF_SECONDS = 0


def _is_number(value):
    # bool subclasses int; reject it so JSON `true` isn't read as 1.
    # json.load accepts NaN/Infinity; reject them so sleep/timeout stay bounded.
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


def _is_valid_retries(value):
    return _is_number(value) and isinstance(value, int) and value >= 1


def _is_valid_timeout(value):
    return _is_number(value) and value > 0


def _is_valid_backoff(value):
    return _is_number(value) and value >= 0


def _read_config(path):
    try:
        with open(path) as config_file:
            config = json.load(config_file)
    except FileNotFoundError:
        logger.warning("Config file %s not found; using defaults", path)
        return {}
    except (OSError, json.JSONDecodeError) as err:
        logger.warning("Config file %s unreadable (%s); using defaults", path, err)
        return {}

    if not isinstance(config, dict):
        logger.warning(
            "Config file %s top level is %s, not an object; using defaults",
            path, type(config).__name__,
        )
        return {}
    return config


def _get_setting(config, key, default, is_valid, requirement):
    value = config.get(key, default)
    if not is_valid(value):
        logger.warning(
            "Config %s=%r invalid (must be %s); using default %r",
            key, value, requirement, default,
        )
        return default
    return value


def ld(p):
    config = _read_config(p)
    retries = _get_setting(
        config, "retries", DEFAULT_RETRIES, _is_valid_retries, "an integer >= 1"
    )
    timeout_seconds = _get_setting(
        config, "timeout", DEFAULT_TIMEOUT_SECONDS, _is_valid_timeout, "a number > 0"
    )
    backoff_seconds = _get_setting(
        config, "backoff_seconds", DEFAULT_BACKOFF_SECONDS, _is_valid_backoff, "a number >= 0"
    )
    return retries, timeout_seconds, backoff_seconds


def snd(u, pl, r, to, backoff=DEFAULT_BACKOFF_SECONDS):
    if not _is_valid_retries(r):
        raise ValueError(f"retries must be an integer >= 1, got {r!r}")
    if not _is_valid_timeout(to):
        raise ValueError(f"timeout must be a number > 0, got {to!r}")
    if not _is_valid_backoff(backoff):
        raise ValueError(f"backoff must be a number >= 0, got {backoff!r}")

    for attempt in range(1, r + 1):
        try:
            req = urllib.request.Request(u, data=pl)
            with urllib.request.urlopen(req, timeout=to) as response:
                return response.read()
        # OSError covers URLError, HTTPError, timeouts, and connection resets.
        # Malformed URLs raise ValueError and propagate: retrying can't fix them.
        except (OSError, http.client.HTTPException) as err:
            logger.warning(
                "Notify attempt %d/%d to %s failed: %s", attempt, r, u, err
            )
        if attempt < r:
            time.sleep(backoff)

    logger.error("Notify to %s failed after %d attempts", u, r)
    return None
```

**What changed beyond backoff:**

- **Backoff:** `backoff_seconds` is read from config (default `0`, so behavior is unchanged when it's absent). It is passed to `snd` as an optional `backoff` argument, and `snd` sleeps only between attempts.
- **Breaking change:** `ld()` now returns a 3-tuple `(retries, timeout, backoff_seconds)`. Any caller doing `r, to = ld(path)` must be updated to unpack three values.
- **Error handling:** I replaced the bare `except:` clauses, which also swallowed `KeyboardInterrupt` and programming errors, with specific exceptions. Every failed attempt and every final failure is now logged, where before they were silently discarded.
- **Config validation:** Bad values such as a negative retry count, a string timeout, or `NaN` fall back to defaults with a warning. Before, they were passed straight through. `snd` raises `ValueError` on invalid arguments because those come from the caller, not the config.
- **Resource handling:** The config file and HTTP response are now closed via `with`.
- **Cleanup:** I removed the commented-out old loader and added named constants for the defaults.

I kept the public names `ld` and `snd` so existing callers keep working. If you control all call sites, renaming them to something like `config_load` / `notify_send` would be a worthwhile follow-up.
